#!/bin/bash
#
# This script runs the image generated by the docker build script
# using docker run command, where:
#   --rm  automatically removes the container and on exit
#   -i  keeps the standard input open
#   -t  provides a terminal as a interactive shell within container
#   --volumes  are file systems mounted on docker container to preserve
# data generated during the yocto build and these are stored on the host.
# Left side being an absolute path on the host machine, right side being
# an absolute path inside the container.
#

# source the common variables
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
. $ROOT_DIR/env.sh

if [[ $PWD != $HOME* && $(whoami) != "root" ]]; then
    echo "Error: Current directory is outside $HOME"
    exit 1
fi

if [ "$#" -gt 0 ]; then
  COMMAND="$*"
else
  COMMAND="exec bash"
fi

# Option to put the Yocto builds/ directory in a volume
# Defaults to true on macOS (needed due to hard link limitation), and false otherwise
if [ -z "$BUILD_IN_VOLUME" ]; then
  if [[ "$OSTYPE" == "darwin"* ]]; then
    echo "Detected macOS host, automatically setting BUILD_IN_VOLUME to true"
    BUILD_IN_VOLUME=true
  else
    BUILD_IN_VOLUME=false
  fi
fi

BUILDS_DIR="${PWD}/builds"
if [ "$BUILD_IN_VOLUME" = "true" ] || [ "$BUILD_IN_VOLUME" = "1" ]; then
  echo "Using volume for Yocto builds directory: ${BUILDS_DIR}"
  CONTAINER_RUN_PARAMS="${CONTAINER_RUN_PARAMS} --volume meta-swift-examples:${BUILDS_DIR}"
fi

# run the docker image
$CONTAINER_ENGINE run -it --rm \
  --device /dev/net/tun \
  --cap-add=NET_ADMIN \
  --volume "${HOME}":"${HOME}" \
  ${CONTAINER_RUN_PARAMS} \
  "${IMAGE_TAG}" \
  /bin/bash -c "sudo chown $(id -u):$(id -g) ${BUILDS_DIR} && $COMMAND"
